\echo === PART 1 -> data/eicu_extract_cohort_stays.csv ===
\copy (WITH base AS ( SELECT p.patientunitstayid, p.uniquepid, p.hospitalid, p.gender, p.age, p.unittype, p.unitvisitnumber, p.hospitaladmitsource, p.unitdischargeoffset, p.hospitaldischargeoffset, p.hospitaldischargestatus, p.hospitaldischargeyear, CASE WHEN p.age = '> 89' THEN 90 WHEN p.age ~ '^[0-9]+$' THEN p.age::numeric ELSE NULL END AS age_num FROM eicu_crd.patient p WHERE p.unitvisitnumber = 1 ), sep AS ( SELECT DISTINCT d.patientunitstayid FROM eicu_crd.diagnosis d WHERE d.icd9code LIKE '038%' OR d.icd9code LIKE '99591%' OR d.icd9code LIKE '99592%' OR d.icd9code LIKE '78552%' OR d.icd9code LIKE 'A40%' OR d.icd9code LIKE 'A41%' OR d.icd9code LIKE 'R652%' OR d.icd9code LIKE 'R65.2%' OR lower(d.diagnosisstring) LIKE '%sepsis%' OR lower(d.diagnosisstring) LIKE '%septic%' ), trop AS ( SELECT l.patientunitstayid, count(*) AS n_rows_72h, count(*) FILTER (WHERE l.labresult IS NULL) AS n_null, count(*) FILTER (WHERE l.labresult <= 0) AS n_nonpos, count(*) FILTER (WHERE lower(coalesce(l.labmeasurenameinterface,'')) IN ('mg/ml','mg/dl')) AS n_unit_implausible, count(*) FILTER (WHERE l.labresulttext ILIKE '%<%' OR l.labresulttext ILIKE '%less%' OR l.labresulttext ILIKE '%detect%') AS n_below_detect, count(*) FILTER (WHERE l.labresult > 0 AND lower(coalesce(l.labmeasurenameinterface,'')) NOT IN ('mg/ml','mg/dl')) AS n_meas, min(l.labresultoffset) FILTER (WHERE l.labresult > 0 AND lower(coalesce(l.labmeasurenameinterface,'')) NOT IN ('mg/ml','mg/dl')) AS first_offset_min, max(l.labresultoffset) FILTER (WHERE l.labresult > 0 AND lower(coalesce(l.labmeasurenameinterface,'')) NOT IN ('mg/ml','mg/dl')) AS last_offset_min, (array_agg(l.labresult ORDER BY l.labresultoffset ASC) FILTER (WHERE l.labresult > 0 AND lower(coalesce(l.labmeasurenameinterface,'')) NOT IN ('mg/ml','mg/dl')))[1] AS first_val, (array_agg(l.labresult ORDER BY l.labresultoffset DESC) FILTER (WHERE l.labresult > 0 AND lower(coalesce(l.labmeasurenameinterface,'')) NOT IN ('mg/ml','mg/dl')))[1] AS last_val, max(l.labresult) FILTER (WHERE l.labresult > 0 AND lower(coalesce(l.labmeasurenameinterface,'')) NOT IN ('mg/ml','mg/dl')) AS max_val FROM eicu_crd.lab l WHERE l.labname = 'troponin - I' AND l.labresultoffset >= 0 AND l.labresultoffset <= 4320 GROUP BY l.patientunitstayid ) SELECT b.patientunitstayid, b.uniquepid, b.hospitalid, b.hospitaldischargeyear, b.gender, b.age_num, b.age AS age_raw, b.unittype, b.hospitaladmitsource, b.unitdischargeoffset, b.hospitaldischargeoffset, b.hospitaldischargestatus, t.n_rows_72h, t.n_null, t.n_nonpos, t.n_unit_implausible, t.n_below_detect, t.n_meas, t.first_offset_min, t.last_offset_min, t.first_val, t.last_val, t.max_val, (b.hospitaldischargeoffset - 4320) / 1440.0 AS days_from_landmark_to_discharge, CASE WHEN b.hospitaldischargestatus = 'Expired' THEN 1 ELSE 0 END AS in_hosp_death FROM base b JOIN sep s ON s.patientunitstayid = b.patientunitstayid JOIN trop t ON t.patientunitstayid = b.patientunitstayid WHERE b.age_num >= 18 AND b.age_num <= 90 AND b.unitdischargeoffset >= 1440 AND b.hospitaldischargeoffset >= 4320 AND b.hospitaldischargestatus IN ('Alive','Expired') ORDER BY b.hospitalid, b.patientunitstayid) TO 'data/eicu_extract_cohort_stays.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')

\echo === PART 2 -> data/eicu_extract_site_unit_lod.csv ===
\copy (SELECT p.hospitalid, count(DISTINCT p.patientunitstayid) AS stays_with_any_ctni, count(*) AS ctni_rows, count(DISTINCT lower(coalesce(l.labmeasurenameinterface,''))) AS n_interface_units, string_agg(DISTINCT coalesce(l.labmeasurenameinterface,'(null)'), '|') AS interface_units, min(l.labresult) AS min_result, max(l.labresult) AS max_result, count(*) FILTER (WHERE l.labresult <= 0) AS n_nonpos, count(*) FILTER (WHERE l.labresulttext ILIKE '%<%' OR l.labresulttext ILIKE '%less%' OR l.labresulttext ILIKE '%detect%') AS n_below_detect, min(l.labresultoffset) AS min_offset, max(l.labresultoffset) AS max_offset FROM eicu_crd.lab l JOIN eicu_crd.patient p ON p.patientunitstayid = l.patientunitstayid WHERE l.labname = 'troponin - I' AND l.labresultoffset >= 0 AND l.labresultoffset <= 4320 GROUP BY p.hospitalid ORDER BY stays_with_any_ctni DESC) TO 'data/eicu_extract_site_unit_lod.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')

\echo === PART 3 -> data/eicu_extract_site_hospital.csv ===
\copy (SELECT * FROM eicu_crd.hospital ORDER BY hospitalid) TO 'data/eicu_extract_site_hospital.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')

\echo === PART 4 -> data/eicu_extract_apache.csv ===
\copy (SELECT a.patientunitstayid, max(a.apacheversion) AS apacheversion, max(a.acutephysiologyscore) AS acute_physiology_score, max(a.apachescore) AS apache_score, max(a.predictedhospitalmortality) AS pred_hosp_mortality, max(a.actualhospitalmortality) AS actual_hosp_mortality FROM eicu_crd.apachepatientresult a GROUP BY a.patientunitstayid ORDER BY a.patientunitstayid) TO 'data/eicu_extract_apache.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')

\echo === PART 5 -> data/eicu_extract_window72.csv ===
\copy (WITH coh AS ( SELECT DISTINCT l.patientunitstayid FROM eicu_crd.lab l WHERE l.labname = 'troponin - I' AND l.labresultoffset >= 0 AND l.labresultoffset <= 4320 ), vaso AS ( SELECT d.patientunitstayid, 1 AS vaso72 FROM eicu_crd.infusiondrug d WHERE d.infusionoffset > 2880 AND d.infusionoffset <= 4320 AND (lower(d.drugname) LIKE '%norepinephrine%' OR lower(d.drugname) LIKE '%epinephrine%' OR lower(d.drugname) LIKE '%vasopressin%' OR lower(d.drugname) LIKE '%phenylephrine%' OR lower(d.drugname) LIKE '%dopamine%' OR lower(d.drugname) LIKE '%dobutamine%') GROUP BY d.patientunitstayid ), lac AS ( SELECT l.patientunitstayid, (array_agg(l.labresult ORDER BY l.labresultoffset DESC))[1] AS lac72 FROM eicu_crd.lab l WHERE l.labname = 'lactate' AND l.labresult IS NOT NULL AND l.labresultoffset > 2880 AND l.labresultoffset <= 4320 GROUP BY l.patientunitstayid ) SELECT c.patientunitstayid, COALESCE(v.vaso72, 0) AS vaso72, lc.lac72 AS lac72 FROM coh c LEFT JOIN vaso v ON v.patientunitstayid = c.patientunitstayid LEFT JOIN lac lc ON lc.patientunitstayid = c.patientunitstayid ORDER BY c.patientunitstayid) TO 'data/eicu_extract_window72.csv' WITH (FORMAT csv, HEADER true, ENCODING 'UTF8')
